Claude CodeClaude DesktopCursor <pre><code>claude mcp add --transport http kaisho \
  http://localhost:8765/mcp/ \
  --header "Authorization: Bearer $(cat ~/.kaisho/mcp-token)"
</code></pre> <p><code>~/Library/Application Support/Claude/claude_desktop_config.json</code>:</p> <pre><code>{
  "mcpServers": {
    "kaisho": {
      "url": "http://localhost:8765/mcp/",
      "headers": {
        "Authorization": "Bearer YOUR_TOKEN_HERE"
      }
    }
  }
}
</code></pre> <p><code>.cursor/mcp.json</code>:</p> <pre><code>{
  "mcpServers": {
    "kaisho": {
      "url": "http://localhost:8765/mcp/",
      "headers": {
        "Authorization": "Bearer YOUR_TOKEN_HERE"
      }
    }
  }
}
</code></pre>
